<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {api,type Page} from '../../api/http'
import {errorMessage} from '../../api/http'
import {bookApi} from '../../api/ebrBook'
import {useAuthStore} from '../../stores/auth'
import ProcessVersionPicker from './ProcessVersionPicker.vue'
import type {EbrDetail,EbrSummary} from './types'
import {bookKinds,newBookEntry,type BookDefinition,type BookTemplate,type BookEntry} from './bookModel'
const auth=useAuthStore(),templates=ref<BookTemplate[]>([]),products=ref<Array<{id:string;productName:string;specification:string}>>([]),ebr=ref<EbrSummary[]>([]),printTemplates=ref<Array<{id:string;templateName:string;templateRevision:number}>>([]),reference=ref<EbrDetail|null>(null),busy=ref(false),error=ref(''),notice=ref(''),code=ref(''),reason=ref(''),open=ref(false)
const definition=ref<BookDefinition>({varietyCode:'',varietyName:'',mappings:[],entries:[]}),forms=computed(()=>reference.value?.definition.forms??[])
async function load(){busy.value=true;error.value='';try{templates.value=await bookApi.templates();const p=await api<Page<{id:string;productName:string;specification:string}>>({url:'/products',params:{size:100}});products.value=p.items;const t=await api<Page<EbrSummary>>({url:'/ebr/templates',params:{size:100,status:'EFFECTIVE'}});ebr.value=t.items;if(auth.can('print:template:view'))printTemplates.value=(await api<Page<{id:string;templateName:string;templateRevision:number}>>({url:'/printing/templates',params:{businessType:'EBR_PROCESS_FORM',status:'PUBLISHED',size:100}})).items}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
function edit(t?:BookTemplate){definition.value=t?JSON.parse(JSON.stringify(t.definition)):{varietyCode:'',varietyName:'',mappings:[{productId:'',processPackageId:'',ebrTemplateVersionId:''}],entries:[]};code.value=t?.templateCode??'';reason.value='';reference.value=null;open.value=true;refreshFields()}
async function refreshFields(){const first=definition.value.mappings?.[0]?.ebrTemplateVersionId;if(first)try{reference.value=await api<EbrDetail>({url:`/ebr/templates/${first}`})}catch(e){error.value=errorMessage(e)}}
function selectForm(entry:BookEntry){const form=forms.value.find(f=>f.formCode===entry.formCode);if(!form)return;entry.fields=form.fields.map(f=>f.fieldCode);entry.operationCode=reference.value?.operationChoices.find(o=>o.id===form.operationDefId)?.operationCode??null;entry.title=form.formName}
function changeKind(e:BookEntry){if(e.kind!=='FORM'){e.formCode=null;e.printTemplateVersionId=null;e.fields=[];e.scope='BATCH';e.operationCode=null}}
async function save(){busy.value=true;error.value='';try{await bookApi.create(code.value,definition.value,reason.value);open.value=false;notice.value='已生成新的不可覆盖草稿版本；审批后发布。';await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
const pendingTransition=ref<{template:BookTemplate;action:'publish'|'deactivate'}|null>(null),transitionReason=ref('')
function transition(template:BookTemplate,action:'publish'|'deactivate'){transitionReason.value='';pendingTransition.value={template,action}}
async function confirmTransition(){const pending=pendingTransition.value,why=transitionReason.value.trim();if(!pending||!why)return;busy.value=true;error.value='';try{await bookApi.transition(pending.template,pending.action,why);pendingTransition.value=null;await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}

onMounted(load)
</script>
<template><main data-ui-template="T1" class="admin-page master-page book-template-page"><header class="admin-page-header"><div><h1>生产批记录册模板</h1></div><a-button v-if="auth.can('ebr:template:create')" type="primary" @click="edit()">新增册模板</a-button></header><a-alert v-if="error" type="error" :message="error" show-icon/><a-alert v-if="notice" type="success" :message="notice" show-icon/><a-card title="版本列表"><a-table :scroll="{x:750}" :data-source="templates" row-key="id" :loading="busy" :pagination="false" :columns="[{title:'模板编码',dataIndex:'templateCode'},{title:'版本',dataIndex:'revision'},{title:'状态',dataIndex:'status'},{title:'品种',key:'variety'},{title:'操作',key:'actions'}]"><template #bodyCell="{column,record}"><span v-if="column.key==='variety'">{{record.definition.varietyName}}</span><a-space v-if="column.key==='actions'"><a-button type="link" @click="edit(record)">{{auth.can('ebr:template:create')?'查看 / 新版本':'查看'}}</a-button><a-button v-if="record.status==='DRAFT'&&auth.can('ebr:template:publish')" type="link" @click="transition(record,'publish')">发布</a-button><a-button v-if="record.status==='PUBLISHED'&&auth.can('ebr:template:publish')" type="link" @click="transition(record,'deactivate')">停用</a-button></a-space></template></a-table></a-card><a-modal :open="!!pendingTransition" :title="pendingTransition?.action==='publish'?'发布册模板':'停用册模板'" :confirm-loading="busy" :ok-button-props="{disabled:!transitionReason.trim()}" @ok="confirmTransition" @cancel="pendingTransition=null"><label>操作原因<a-textarea v-model:value="transitionReason" aria-label="操作原因" maxlength="1000"/></label><p>记录操作者及原因；已发布内容不可覆盖。</p></a-modal><a-drawer v-model:open="open" title="批记录册受控版本" :width="'min(1080px,96vw)'" :destroy-on-close="true"><form class="book-template-form" @submit.prevent="save"><a-card title="品种与册模板"><div class="form-grid"><label>模板编码<a-input v-model:value="code" required maxlength="64"/></label><label>品种编码<a-input v-model:value="definition.varietyCode" required maxlength="64"/></label><label>品种名称<a-input v-model:value="definition.varietyName" required maxlength="120"/></label></div></a-card><a-card title="规格产品适用映射"><section v-for="(mapping,index) in (definition.mappings??[])" :key="index" class="mapping-row"><label>规格产品<a-select v-model:value="mapping.productId" show-search :option-filter-prop="'label'" :options="products.map(p=>({value:p.id,label:`${p.productName} · ${p.specification||'未提供规格'}`}))"/></label><ProcessVersionPicker v-model="mapping.packageVersionId"/><label>已生效eBR版本<a-select show-search option-filter-prop="label" v-model:value="mapping.ebrTemplateVersionId" @change="refreshFields" :options="ebr.filter(t=>t.packageVersionId===mapping.packageVersionId).map(t=>({value:t.id,label:`${t.templateName||'未命名（历史模板）'} · ${t.templateCode} V${t.version}`}))"/></label><a-button :disabled="(definition.mappings??[]).length===1" @click="(definition.mappings??[]).splice(index,1)">移除映射</a-button></section><a-button @click="(definition.mappings??[]).push({productId:'',processPackageId:'',ebrTemplateVersionId:''})">增加规格映射</a-button><p>各映射保持独立产品ID；发布时校验工序标识和同表字段结构一致。</p></a-card><a-card title="有序章节与目录"><section v-for="(entry,index) in definition.entries" :key="entry.code+index" class="entry-card"><div class="form-grid"><label>目录项编码<a-input v-model:value="entry.code" required maxlength="64"/></label><label>章节<a-input v-model:value="entry.chapter" required/></label><label>表格标题<a-input v-model:value="entry.title" required/></label><label>顺序<a-input-number v-model:value="entry.order" :min="1"/></label><label>来源类型<a-select show-search option-filter-prop="label" v-model:value="entry.kind" @change="changeKind(entry)" :options="Object.entries(bookKinds).map(([value,label])=>({value,label}))"/></label><label>必需项<a-switch v-model:checked="entry.required" @change="entry.minCount=entry.required?Math.max(1,entry.minCount):0"/></label><label>至少来源份数<a-input-number v-model:value="entry.minCount" :min="entry.required?1:0" :max="1000"/></label><template v-if="entry.kind==='FORM'"><label>过程表单<a-select show-search option-filter-prop="label" v-model:value="entry.formCode" @change="selectForm(entry)" :options="forms.map(f=>({value:f.formCode,label:`${f.formName} · ${f.formCode}`}))"/></label><label>稳定工序编码<a-input v-model:value="entry.operationCode" required/></label><label>实例范围<a-select show-search option-filter-prop="label" v-model:value="entry.scope" :options="[{value:'OPERATION',label:'各实际工序实例'},{value:'BATCH',label:'整批一份（分装/包装）'}]"/></label><label class="wide">表格字段<a-select show-search option-filter-prop="label" v-model:value="entry.fields" mode="multiple" :options="(forms.find(f=>f.formCode===entry.formCode)?.fields??[]).map(f=>({value:f.fieldCode,label:f.label}))"/></label><label class="wide">受控Word打印版本（可选）<a-select show-search option-filter-prop="label" v-model:value="entry.printTemplateVersionId" allow-clear :options="printTemplates.map(p=>({value:p.id,label:`${p.templateName} V${p.templateRevision}`}))"/></label></template><label v-if="entry.kind==='ATTACHMENTS'" class="wide">受控附件ID（保留原件）<a-select show-search option-filter-prop="children" v-model:value="entry.attachmentIds" mode="tags"/></label></div><a-button danger @click="definition.entries.splice(index,1)">移除此目录项</a-button></section><a-button @click="definition.entries.push(newBookEntry(definition.entries.length+1))">增加目录项</a-button></a-card><a-card title="版本原因"><a-textarea v-model:value="reason" required maxlength="1000" placeholder="本次新版本的原因"/><p>保存生成新草稿，不覆盖已发布内容；历史批次不自动换版。</p><a-button v-if="auth.can('ebr:template:create')" type="primary" html-type="submit" :loading="busy">保存新草稿版本</a-button></a-card></form></a-drawer></main></template>
<style scoped>.book-template-page{min-width:0;max-width:100%;overflow:hidden}.book-template-form{display:grid;gap:18px}.form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.form-grid label,.mapping-row>label{display:grid;gap:7px;font-size:13px}.wide{grid-column:span 3}.mapping-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;border-bottom:1px solid #e3e8f0;padding:15px 0}.entry-card{border:1px solid #dce3ed;border-radius:6px;padding:18px;margin-bottom:16px}.entry-card>button{margin-top:14px}p{color:#68778c;font-size:13px}@media(max-width:720px){.form-grid,.mapping-row{grid-template-columns:1fr}.wide{grid-column:span 1}}</style>
